#define main unused_array_main
#include "../world_atlas_case/array_probe.c"
#undef main
static GLuint source[3];static uint32_t metadata[LIMIT][12];
static const char *nvs="#version 300 es\nin vec3 a_position;in vec4 a_colour;in vec3 a_uvq;uniform mat4 u_projection;out mediump vec4 v_colour;out highp vec3 v_uvq;void main(){gl_Position=u_projection*vec4(a_position,1.0);v_colour=a_colour;v_uvq=a_uvq;}";
static const char *nfs="#version 300 es\nprecision highp float;precision highp int;uniform highp usampler2D u_pens;uniform highp usampler2D u_map;uniform lowp sampler2D u_palette;uniform uvec4 u_shape,u_origin,u_decode;uniform bool u_oriented,u_priority;in mediump vec4 v_colour;in highp vec3 v_uvq;out vec4 output_colour;\n"
"uint nearest(float f,uint d){if(f<=0.0)return 0u;if(f>=1.0)return d-1u;uint bits=floatBitsToUint(f);uint e=(bits>>23u)&255u;if(e<115u)return 0u;uint s=150u-e;uint m=(bits&8388607u)|8388608u;uint a=(m&65535u)*d;uint b=(m>>16u)*d;uint lo=a+(b<<16u);uint hi=(b>>16u)+(lo<a?1u:0u);uint q=s>=32u?hi>>(s-32u):(lo>>s)|(hi<<(32u-s));return min(q,d-1u);}\n"
"void main(){vec2 uv=v_uvq.xy/v_uvq.z;vec4 texel=vec4(1.0);if((u_decode.w&1u)==0u){uvec2 p=uvec2(nearest(uv.x,u_shape.x),nearest(uv.y,u_shape.y));uint u=(u_origin.x+p.x*u_shape.z)&4095u;uint v=((u_origin.y+p.y*u_shape.w)&4095u)|(u_origin.z*4096u);uint entry=texelFetch(u_map,ivec2(u>>4u,v>>4u),0).r;uint tile=entry;uint x=u&15u,y=v&15u;uint raw=0u;if(!u_oriented){tile=entry&131071u;uint at=(entry>>16u)&14u;if((at&4u)!=0u)x=15u-x;if((at&2u)!=0u)y=15u-y;if((at&8u)!=0u){uint t=x;x=y;y=t;}}if(u_oriented||tile<65536u)raw=texelFetch(u_pens,ivec2((tile&255u)*16u+x,(tile>>8u)*16u+y),0).r;uint pen=(u_decode.x+((raw>>u_decode.y)&u_decode.z))&255u;if(pen==0u&&(u_decode.w&2u)==0u)discard;texel=texelFetch(u_palette,ivec2(pen,u_origin.w),0);}vec4 c=v_colour*texel;output_colour=u_priority?vec4(c.rgb,v_colour.a):c;}";
static void *readfile(const char *dir,const char *name,size_t bytes){char p[1024];snprintf(p,sizeof p,"%s/%s",dir,name);FILE *f=fopen(p,"rb");CHECK(f);void *b=malloc(bytes);CHECK(b&&fread(b,1,bytes,f)==bytes);CHECK(fgetc(f)==EOF);fclose(f);return b;}
static GLuint integer_texture(int w,int h,GLenum internal,GLenum format,GLenum type,void *data){GLuint t;glGenTextures(1,&t);glBindTexture(GL_TEXTURE_2D,t);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);glTexImage2D(GL_TEXTURE_2D,0,internal,w,h,0,format,type,data);return t;}
static void native_submit(GLuint p,int oriented,unsigned char *pixels,double *cpu,double *wall){double start=now(CLOCK_MONOTONIC),begin=now(CLOCK_THREAD_CPUTIME_ID);glBindFramebuffer(GL_FRAMEBUFFER,fb);glViewport(0,0,640,480);glDisable(GL_CULL_FACE);glDisable(GL_SCISSOR_TEST);if(priority)glDisable(GL_BLEND);else{glEnable(GL_BLEND);glBlendFunc(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA);}glEnable(GL_DEPTH_TEST);glDepthFunc(GL_LEQUAL);glDepthMask(GL_TRUE);glClearDepthf(1);glClearColor(bg[0],bg[1],bg[2],priority?0:1);glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);glEnable(GL_SCISSOR_TEST);glUseProgram(p);const float matrix[16]={2.f/640,0,0,0,0,-2.f/480,0,0,0,0,1,0,-1,1,0,1};glUniformMatrix4fv(glGetUniformLocation(p,"u_projection"),1,GL_FALSE,matrix);glUniform1i(glGetUniformLocation(p,"u_priority"),priority);glUniform1i(glGetUniformLocation(p,"u_oriented"),oriented);const char *names[]={"u_pens","u_map","u_palette"};for(int i=0;i<3;i++){glActiveTexture(GL_TEXTURE0+i);glBindTexture(GL_TEXTURE_2D,source[i]);glUniform1i(glGetUniformLocation(p,names[i]),i);}glBindBuffer(GL_ARRAY_BUFFER,buffer);vertex *v=malloc(nv*sizeof *v);for(int i=0;i<nd;i++)memcpy(v+ds[i].first,ds[i].v,ds[i].count*sizeof *v);glBufferData(GL_ARRAY_BUFFER,nv*sizeof *v,v,GL_STREAM_DRAW);free(v);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,40,(void*)0);glVertexAttribPointer(1,4,GL_FLOAT,GL_FALSE,40,(void*)12);glVertexAttribPointer(2,3,GL_FLOAT,GL_FALSE,40,(void*)28);for(int i=0;i<3;i++)glEnableVertexAttribArray(i);glDisableVertexAttribArray(3);GLint locations[3]={glGetUniformLocation(p,"u_shape"),glGetUniformLocation(p,"u_origin"),glGetUniformLocation(p,"u_decode")};for(int i=0;i<nd;i++){draw *d=ds+i;for(int j=0;j<3;j++)glUniform4uiv(locations[j],1,metadata[d->tex]+j*4);glScissor(d->scissor[0],d->scissor[1],d->scissor[2],d->scissor[3]);glDrawArrays(GL_TRIANGLES,d->first,d->count);}*cpu=now(CLOCK_THREAD_CPUTIME_ID)-begin;glFinish();*wall=now(CLOCK_MONOTONIC)-start;if(pixels)glReadPixels(0,0,640,480,GL_RGBA,GL_UNSIGNED_BYTE,pixels);CHECK(glGetError()==GL_NO_ERROR);glActiveTexture(GL_TEXTURE0);}
int main(int argc,char **argv){CHECK(argc==3);CHECK(!SDL_Init(SDL_INIT_VIDEO));SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK,SDL_GL_CONTEXT_PROFILE_ES);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,3);SDL_Window *w=SDL_CreateWindow("native texture gate",0,0,640,480,SDL_WINDOW_OPENGL);CHECK(w&&SDL_GL_CreateContext(w));SDL_GL_SetSwapInterval(0);printf("GPU=%s VERSION=%s\n",glGetString(GL_RENDERER),glGetString(GL_VERSION));load(argv[1]);void *m=readfile(argv[2],"metadata.bin",nr*48);memcpy(metadata,m,nr*48);free(m);for(int i=0;i<nr;i++)res[i].tex=texture(res[i].w,res[i].h,res[i].rgba);GLuint target=texture(640,480,NULL),depthbuf;glGenFramebuffers(1,&fb);glBindFramebuffer(GL_FRAMEBUFFER,fb);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,target,0);glGenRenderbuffers(1,&depthbuf);glBindRenderbuffer(GL_RENDERBUFFER,depthbuf);glRenderbufferStorage(GL_RENDERBUFFER,depth==16?GL_DEPTH_COMPONENT16:GL_DEPTH_COMPONENT24_OES,640,480);glFramebufferRenderbuffer(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_RENDERBUFFER,depthbuf);CHECK(glCheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE);glGenBuffers(1,&buffer);GLuint original=program(vs,fs),native=program(nvs,nfs);unsigned char *base=malloc(640*480*4),*candidate=malloc(640*480*4);double cpu,wall;submit(original,0,0,base,&cpu,&wall);void *reference=readfile(argv[1],"reference.rgba",640*480*4);unsigned diff=compare("baseline.rgba",reference,base);if(strstr((char*)glGetString(GL_RENDERER),"Mali"))CHECK(!diff);free(reference);int failures=0;for(int oriented=0;oriented<2;oriented++){void *b=readfile(argv[2],oriented?"oriented.bin":"raw.bin",4096*(oriented?4112:4096));source[0]=integer_texture(4096,oriented?4112:4096,GL_R8UI,GL_RED_INTEGER,GL_UNSIGNED_BYTE,b);free(b);b=readfile(argv[2],oriented?"oriented-map.bin":"raw-map.bin",4194304);source[1]=integer_texture(256,4096,GL_R32UI,GL_RED_INTEGER,GL_UNSIGNED_INT,b);free(b);b=readfile(argv[2],"palette.bin",131072);source[2]=texture(256,128,b);free(b);glFinish();native_submit(native,oriented,candidate,&cpu,&wall);diff=compare(oriented?"oriented.rgba":"raw.rgba",base,candidate);failures+=diff!=0;printf("CORRECTNESS layout=%d differing_pixels=%u\n",oriented,diff);for(int warm=0;warm<5;warm++){submit(original,0,0,NULL,&cpu,&wall);native_submit(native,oriented,NULL,&cpu,&wall);}for(int s=0;s<30;s++)for(int j=0;j<2;j++){int mode=(s+j)%2;if(mode)native_submit(native,oriented,NULL,&cpu,&wall);else submit(original,0,0,NULL,&cpu,&wall);printf("TIMING layout=%d sample=%d mode=%d cpu_ms=%.6f completion_ms=%.6f\n",oriented,s,mode,cpu*1000,wall*1000);}glDeleteTextures(3,source);glFinish();}printf("GATE failures=%d\n",failures);return failures?1:0;}
